let language = localStorage.getItem('scanbridge-language') || 'en';
const $ = selector => document.querySelector(selector), lang = $('.language-toggle'), theme = $('.theme-toggle'), themeLabel = $('.theme-label');
function setTheme(value){const dark=value==='dark';document.body.classList.toggle('dark-mode',dark);theme.setAttribute('aria-pressed',String(dark));themeLabel.textContent=language==='ar'?(dark?'فاتح':'داكن'):(dark?'Light':'Dark');localStorage.setItem('scanbridge-theme',value);}
function render(){const text=ui[language];document.documentElement.lang=language;document.documentElement.dir=language==='ar'?'rtl':'ltr';document.querySelectorAll('[data-ui]').forEach(element=>element.textContent=text[element.dataset.ui]);lang.textContent=language==='ar'?'English':'العربية';}
lang.addEventListener('click',()=>{language=language==='ar'?'en':'ar';localStorage.setItem('scanbridge-language',language);render();setTheme(localStorage.getItem('scanbridge-theme')||'light');});
theme.addEventListener('click',()=>setTheme(document.body.classList.contains('dark-mode')?'light':'dark'));
render();setTheme(localStorage.getItem('scanbridge-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'));
